     1	#!/usr/bin/env node
     2	// SessionEnd hook: commit and push the repo this session worked in, so new and
     3	// changed files reach GitHub without waiting for /closeout. Added 2026-10-19.
     4	//
     5	// Why: Eric works on the Mac and the Windows laptop. Anything left uncommitted
     6	// on one machine is invisible on the other. This makes "push at the end" the
     7	// default instead of a habit to remember.
     8	//
     9	// What it does, in order. Any check that fails stops the hook, writes one line
    10	// to .errors.log (surfaced by keystone-unified-snapshot.js at the next session
    11	// start), and leaves the working tree exactly as it was.
    12	//   1. Skip headless/SDK sessions, cloud sessions, and AUTOPUSH_DISABLE=1.
    13	//   2. Find the git repo for the session's cwd. Not a repo: do nothing.
    14	//   3. Skip ~/.claude and everything under it (daily-backup owns those repos,
    15	//      and dotclaude carries GBs of transcripts), the DEV router's ignored
    16	//      subfolders, and any repo with a `.no-autopush` file at its root.
    17	//   4. Skip if a merge or rebase is in progress, HEAD is detached, there are
    18	//      unmerged files, or the branch has no upstream.
    19	//   5. Refuse to commit if any file about to be added looks like a secret,
    20	//      a database, health data, or is over 50 MB. Nothing is committed.
    21	//      .gitignore is respected: ignored files are never looked at.
    22	//   6. `git add -A`, commit "auto: session end (<host>)".
    23	//   7. Fetch. If the remote moved ahead, rebase onto it; on conflict, abort the
    24	//      rebase (the local commit stays) and report.
    25	//   8. Push. A failure is reported; the local commit stays for next time.
    26	//
    27	// Runs synchronously with short git timeouts. Total worst case is about 50s,
    28	// inside the 60s timeout registered in settings.json.
    29	
    30	const { spawnSync } = require('child_process');
    31	const fs = require('fs');
    32	const path = require('path');
    33	const os = require('os');
    34	
    35	const NAME = 'session-autopush';
    36	const HOME = os.homedir();
    37	const ERR_LOG = path.join(HOME, '.claude', 'global-memory', 'transcripts', '.errors.log');
    38	const OK_LOG = path.join(HOME, '.claude', 'global-memory', 'transcripts', 'autopush.log');
    39	const MAX_BYTES = 50 * 1024 * 1024;
    40	
    41	// Files that must never be pushed by an unattended commit, even if a
    42	// .gitignore forgot them. Matched against the repo-relative path.
    43	const BLOCKED = [
    44	  /(^|\/)\.env(\..*)?$/i,
    45	  /\.(pem|key|p12|pfx)$/i,
    46	  /(^|\/)id_(rsa|ed25519|ecdsa)(\.pub)?$/i,
    47	  /credential/i,
    48	  /secret/i,
    49	  /token.*\.json$/i,
    50	  /\.(duckdb|db|sqlite|sqlite3|rds|rdata)$/i,
    51	  /dexa/i,
    52	];
    53	
    54	function log(file, msg) {
    55	  try {
    56	    fs.mkdirSync(path.dirname(file), { recursive: true });
    57	    fs.appendFileSync(file, `[${new Date().toISOString()}] ${NAME}: ${msg}\n`);
    58	  } catch (_) {}
    59	}
    60	const fail = (msg) => { log(ERR_LOG, msg); process.exit(0); };
    61	const quit = () => process.exit(0);
    62	
    63	function git(cwd, args, timeoutSec = 15) {
    64	  const r = spawnSync('git', args, {
    65	    cwd,
    66	    encoding: 'utf8',
    67	    timeout: timeoutSec * 1000,
    68	    windowsHide: true,
    69	    env: { ...process.env, GIT_TERMINAL_PROMPT: '0' },
    70	  });
    71	  return { ok: r.status === 0 && !r.error, out: (r.stdout || '').trim(), err: ((r.stderr || '') + (r.error ? ` ${r.error.message}` : '')).trim() };
    72	}
    73	
    74	function readStdin() {
    75	  try { return JSON.parse(fs.readFileSync(0, 'utf8') || '{}'); } catch (_) { return {}; }
    76	}
    77	
    78	function main() {
    79	  // 1. Who is running.
    80	  const entry = process.env.CLAUDE_CODE_ENTRYPOINT || '';
    81	  if (process.env.CLAUDE_INVOKED_BY || entry.startsWith('sdk')) quit();
    82	  if (process.env.CLAUDE_CODE_REMOTE === 'true') quit();
    83	  if (process.env.AUTOPUSH_DISABLE === '1') quit();
    84	
    85	  // 2. Which repo.
    86	  const input = readStdin();
    87	  const cwd = input.cwd || process.cwd();
    88	  const top = git(cwd, ['rev-parse', '--show-toplevel']);
    89	  if (!top.ok || !top.out) quit();
    90	  const root = path.resolve(top.out);
    91	  const label = path.basename(root);
    92	
    93	  // 3. Repos this hook must not touch.
    94	  const claudeDir = path.resolve(HOME, '.claude');
    95	  const rel = path.relative(claudeDir, root);
    96	  if (rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel))) quit();
    97	  if (fs.existsSync(path.join(root, '.no-autopush'))) quit();
    98	
    99	  // 4. Repo state.
   100	  const gitDir = git(root, ['rev-parse', '--absolute-git-dir']).out;
   101	  if (!gitDir) quit();
   102	  for (const m of ['MERGE_HEAD', 'rebase-merge', 'rebase-apply', 'CHERRY_PICK_HEAD']) {
   103	    if (fs.existsSync(path.join(gitDir, m))) fail(`${label}: skipped, a merge or rebase is in progress. Finish it, then push by hand.`);
   104	  }
   105	  const branch = git(root, ['symbolic-ref', '--quiet', '--short', 'HEAD']);
   106	  if (!branch.ok) fail(`${label}: skipped, HEAD is detached.`);
   107	  const upstream = git(root, ['rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{u}']);
   108	  if (!upstream.ok) fail(`${label}: skipped, branch '${branch.out}' has no upstream. Push it once by hand with -u.`);
   109	
   110	  const status = git(root, ['status', '--porcelain=v1', '-z', '--untracked-files=all']);
   111	  if (!status.ok) fail(`${label}: git status failed: ${status.err}`);
   112	  const entries = status.out.split('\0').filter(Boolean);
   113	  if (entries.some(e => /^(DD|AU|UD|UA|DU|AA|UU) /.test(e))) fail(`${label}: skipped, unmerged files present.`);
   114	
   115	  // 5. Screen what would be added. Renames list the new path first in -z mode.
   116	  const toAdd = [];
   117	  for (let i = 0; i < entries.length; i++) {
   118	    const e = entries[i];
   119	    const code = e.slice(0, 2);
   120	    const p = e.slice(3);
   121	    if (code[0] === 'R' || code[0] === 'C') i++; // skip the "from" path
   122	    if (code.includes('D') && !code.includes('?')) continue; // deletions add nothing
   123	    toAdd.push(p);
   124	  }
   125	  const blocked = [];
   126	  for (const p of toAdd) {
   127	    const norm = p.replace(/\\/g, '/');
   128	    if (BLOCKED.some(re => re.test(norm))) { blocked.push(norm); continue; }
   129	    try {
   130	      const st = fs.statSync(path.join(root, p));
   131	      if (st.isFile() && st.size > MAX_BYTES) blocked.push(`${norm} (${Math.round(st.size / 1048576)} MB)`);
   132	    } catch (_) {}
   133	  }
   134	  if (blocked.length) {
   135	    const shown = blocked.slice(0, 5).join(', ') + (blocked.length > 5 ? `, +${blocked.length - 5} more` : '');
   136	    fail(`${label}: NOT committed. Would have added files that look private or too large: ${shown}. Add them to .gitignore (or commit by hand), then push.`);
   137	  }
   138	
   139	  // 6. Commit.
   140	  let committed = false;
   141	  if (entries.length) {
   142	    const add = git(root, ['add', '-A'], 30);
   143	    if (!add.ok) fail(`${label}: git add failed: ${add.err}`);
   144	    const host = os.hostname().split('.')[0];
   145	    const commit = git(root, ['commit', '-m', `auto: session end (${host})`], 60);
   146	    if (!commit.ok) fail(`${label}: commit failed (a pre-commit hook may have refused it): ${commit.err.slice(0, 300)}`);
   147	    committed = true;
   148	  }
   149	
   150	  // 7. Catch up with the remote.
   151	  const fetch = git(root, ['fetch', '--quiet'], 20);
   152	  if (!fetch.ok) fail(`${label}: ${committed ? 'committed locally, ' : ''}not pushed, fetch failed (offline?): ${fetch.err.slice(0, 200)}`);
   153	  const ahead = parseInt(git(root, ['rev-list', '--count', '@{u}..HEAD']).out || '0', 10);
   154	  const behind = parseInt(git(root, ['rev-list', '--count', 'HEAD..@{u}']).out || '0', 10);
   155	  if (ahead === 0) quit(); // nothing of ours to push
   156	  if (behind > 0) {
   157	    const rb = git(root, ['rebase', '@{u}'], 30);
   158	    if (!rb.ok) {
   159	      git(root, ['rebase', '--abort']);
   160	      fail(`${label}: committed locally, NOT pushed. The other machine pushed changes that conflict. Run 'git pull --rebase' in ${root} and resolve.`);
   161	    }
   162	  }
   163	
   164	  // 8. Push.
   165	  const push = git(root, ['push', '--quiet'], 45);
   166	  if (!push.ok) fail(`${label}: committed locally, NOT pushed: ${push.err.slice(0, 300)}`);
   167	  log(OK_LOG, `${label}: pushed ${branch.out} (${ahead} commit${ahead === 1 ? '' : 's'})`);
   168	}
   169	
   170	try { main(); } catch (e) { fail(`unexpected error: ${e && e.message}`); }
